<?php
// Read first line
$firstLine = trim(fgets(STDIN));
list($n, $m) = explode(' ', $firstLine);

// Initialize grid with padding
// Rows 0 to n+1, Cols 0 to m+1
$grid = array_fill(0, $n + 2, array_fill(0, $m + 2, '.'));

// Read grid lines
for ($i = 1; $i <= $n; $i++) {
    $line = trim(fgets(STDIN));
    // Pad with dots
    $grid[$i] = array_merge(['.'], str_split($line), ['.']);
}

$output = 0;

for ($i = 1; $i <= $n; $i++) {
    for ($j = 1; $j <= $m; $j++) {
        if ($grid[$i][$j] == 'W') {
            if ($grid[$i-1][$j] == 'P' || 
                $grid[$i+1][$j] == 'P' || 
                $grid[$i][$j-1] == 'P' || 
                $grid[$i][$j+1] == 'P') {
                $output++;
            }
        }
    }
}

echo $output . "\n";
?>
```

